'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "¿Vamos mejor o peor que el año pasado, y en qué meses? Tres bandas cuentan la misma historia: arriba la variación en %, en medio la variación en dinero (verde o rojo) y abajo el real (azul) sobre el año anterior (gris). Por CSalcedoDataBI · https://csalcedodatabi.com/deneb/ibcs-tendencia-ano-anterior",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "isValid(datum[''Sales Amount''])"
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "rk"
        }
      ],
      "sort": [
        {
          "field": "Month Date",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rk <= 24"
    },
    {
      "calculate": "datum[''Sales Amount'']",
      "as": "actual"
    },
    {
      "calculate": "isValid(datum[''PY Sales Amount'']) ? datum[''PY Sales Amount''] : null",
      "as": "py"
    },
    {
      "calculate": "datum.py != null ? datum.actual - datum.py : null",
      "as": "deltaAbs"
    },
    {
      "calculate": "datum.py != null && datum.py != 0 ? (datum.actual - datum.py) / datum.py : null",
      "as": "deltaPct"
    },
    {
      "calculate": "''AC''",
      "as": "kind"
    },
    {
      "calculate": "timeFormat(datum[''Month Date''], \"%b ''%y\")",
      "as": "label"
    },
    {
      "calculate": "pbiFormat(abs(datum.actual), (isValid(datum[''Sales Amount__format'']) ? datum[''Sales Amount__format''] : ''$ #,0''), {value: (abs(datum.actual)>=1e9?1e9:abs(datum.actual)>=1e6?1e6:abs(datum.actual)>=1e3?1e3:1), precision: (abs(datum.actual)/(abs(datum.actual)>=1e9?1e9:abs(datum.actual)>=1e6?1e6:abs(datum.actual)>=1e3?1e3:1) >= 100 || abs(datum.actual)/(abs(datum.actual)>=1e9?1e9:abs(datum.actual)>=1e6?1e6:abs(datum.actual)>=1e3?1e3:1) == round(abs(datum.actual)/(abs(datum.actual)>=1e9?1e9:abs(datum.actual)>=1e6?1e6:abs(datum.actual)>=1e3?1e3:1))) ? 0 : 1})",
      "as": "actualLabel"
    },
    {
      "calculate": "datum.py != null ? pbiFormat(abs(datum.py), (isValid(datum[''Sales Amount__format'']) ? datum[''Sales Amount__format''] : ''$ #,0''), {value: (abs(datum.py)>=1e9?1e9:abs(datum.py)>=1e6?1e6:abs(datum.py)>=1e3?1e3:1), precision: (abs(datum.py)/(abs(datum.py)>=1e9?1e9:abs(datum.py)>=1e6?1e6:abs(datum.py)>=1e3?1e3:1) >= 100 || abs(datum.py)/(abs(datum.py)>=1e9?1e9:abs(datum.py)>=1e6?1e6:abs(datum.py)>=1e3?1e3:1) == round(abs(datum.py)/(abs(datum.py)>=1e9?1e9:abs(datum.py)>=1e6?1e6:abs(datum.py)>=1e3?1e3:1))) ? 0 : 1}) : ''—''",
      "as": "pyLabel"
    },
    {
      "calculate": "datum.deltaAbs != null ? (datum.deltaAbs >= 0 ? ''+'' : ''−'') + pbiFormat(abs(datum.deltaAbs), (isValid(datum[''Sales Amount__format'']) ? datum[''Sales Amount__format''] : ''$ #,0''), {value: (abs(datum.deltaAbs)>=1e9?1e9:abs(datum.deltaAbs)>=1e6?1e6:abs(datum.deltaAbs)>=1e3?1e3:1), precision: (abs(datum.deltaAbs)/(abs(datum.deltaAbs)>=1e9?1e9:abs(datum.deltaAbs)>=1e6?1e6:abs(datum.deltaAbs)>=1e3?1e3:1) >= 100 || abs(datum.deltaAbs)/(abs(datum.deltaAbs)>=1e9?1e9:abs(datum.deltaAbs)>=1e6?1e6:abs(datum.deltaAbs)>=1e3?1e3:1) == round(abs(datum.deltaAbs)/(abs(datum.deltaAbs)>=1e9?1e9:abs(datum.deltaAbs)>=1e6?1e6:abs(datum.deltaAbs)>=1e3?1e3:1))) ? 0 : 1}) : ''—''",
      "as": "deltaLabel"
    },
    {
      "calculate": "datum.deltaPct != null ? pbiFormat(datum.deltaPct, ''+0.0%;−0.0%;0.0%'') : ''—''",
      "as": "deltaPctLabel"
    }
  ],
  "padding": {
    "right": 0,
    "left": 0,
    "bottom": 0,
    "top": 4
  },
  "spacing": 10,
